'use client';

import React, { useEffect, useState } from 'react';
import { Breadcrumbs } from '../../components/Breadcrumbs';
// import './admin.css';
import { Product } from '@/types/ProductType';
import { ProductsList } from '@/components/ProductsList';
import Head from 'next/head';
// import './styles/admin.css';

const inputClass =
  'w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all';
const labelClass = 'block text-sm font-medium text-gray-700 mb-1';
const sectionClass = 'bg-white p-6 rounded-xl shadow-sm border border-gray-100';
const btnSecondary =
  'px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors text-sm font-medium';
const btnDanger = 'p-2 text-red-500 hover:text-red-700 hover:bg-red-50 rounded transition-colors';

const startForm = {
  category: '',
  itemId: '',
  price: '',
  fullPrice: '',
  image: '',
  name: '',
  screen: '',
  ram: '',
  camera: '',
  color: '',
  capacity: '',
  cell: [],
  year: '',
  namespaceId: '',
  description: [],
  resolution: '',
  processor: '',
  zoom: '',
};

export const Prisma = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [category, setCategory] = useState<'products' | 'phones' | 'tablets'>('products');
  const [selectedFile, setSelectedFile] = useState([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  console.log(products);

  const [form, setForm] = useState({ ...startForm });

  useEffect(() => {
    setLoading(true);

    const fetchProducts = async () => {
      try {
        const res = await fetch(`/api/products?category=${category}`);
        const data = await res.json();

        if (!res.ok) {
          console.error('Server response:', data);
          throw new Error(`HTTP error! status: ${res.status}`);
        }

        setProducts(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error('Fetch error:', err);
        setProducts([]);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [category]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);

    let imageUrls = [];

    // якщо створюємо новий продукт — фото обов'язкове
    if (!editingId && !selectedFile?.length) {
      return alert('Вибери файл');
    }

    // якщо файли вибрані — завантажуємо
    if (selectedFile?.length > 0) {
      imageUrls = await uploadImages(selectedFile);
    }

    const payload: any = {
      itemId: form.itemId,
      category: form.category,
      name: form.name,
      fullPrice: Number(form.fullPrice) || 0,
      price: Number(form.price) || 0,
      screen: form.screen || '',
      capacity: form.capacity || '',
      color: form.color || '',
      ram: form.ram || '',
      year: form.year || 2000,
      image: imageUrls[0] || form.image, // ← якщо не міняли, беремо старе
    };

    if (form.category) {
      payload.details = {
        name: form.name,
        screen: form.screen || 'unknown',
        ram: form.ram || 'unknown',
        camera: form.camera || 'unknown',
        resolution: form.resolution || 'unknown',
        processor: form.processor || 'unknown',
        zoom: form.zoom || 'unknown',
        capacity: form.capacity || '',
        priceRegular: Number(form.fullPrice) || 0,
        priceDiscount: Number(form.price) || 0,
        color: form.color || '',
        images: imageUrls.length ? imageUrls : [], // ← залишаємо пусто, якщо не оновлювали
        cell: form.cell,
        // capacityAvailable: form.capacityAvailable.split(',').map((s) => s.trim()) || [],
        description: form.description || [],
        namespaceId: form.namespaceId || '',
      };
    }

    try {
      const method = editingId ? 'PUT' : 'POST'; // <---- ГОЛОВНЕ
      const url = '/api/products';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      const data = await res.json();

      if (!res.ok) {
        console.error('Server response:', data);
        throw new Error(`HTTP error! status: ${res.status}`);
      }

      if (editingId) {
        // update
        setProducts((prev) => prev.map((p) => (p.itemId === editingId ? { ...p, ...payload } : p)));

        setEditingId(null);
      } else {
        // create
        setProducts((prev) => [data.product, ...prev]);
      }

      setForm({ ...startForm });
      setSelectedFile([]);
    } catch (err) {
      console.error('Error creating product:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async (product: Product) => {
    setEditingId(product.itemId);

    // 1) Тягнемо деталі
    const detailsRes = await fetch(`/api/products?category=${product.category}`);
    const allDetails = await detailsRes.json();

    // 2) Знаходимо деталі саме цього товару
    const details = allDetails.find((d: any) => d.productId === product.itemId);

    // 3) Сетимо форму
    setForm({
      category: product.category || '',
      itemId: product.itemId || '',
      price: product.price?.toString() || '',
      fullPrice: product.fullPrice?.toString() || '',
      image: product.image || '',
      name: product.name || '',
      screen: product.screen || '',
      ram: product.ram || '',
      color: product.color || '',
      year: product.year?.toString() || '',
      capacity: product.capacity || '',

      // ---------- DETAILS ----------
      // capacityAvailable: details?.capacityAvailable || [],
      // colorsAvailable: details?.colorsAvailable || [],
      images: product.images ?? [],
      resolution: details?.resolution || '',
      processor: details?.processor || '',
      camera: details?.camera || '',
      zoom: details?.zoom || '',
      cell: details?.cell || [],
      description: details?.description || [],
      namespaceId: details?.namespaceId || '',
    });
  };

  const handleDelete = async (itemId: string) => {
    if (!confirm('Точно видалити цей товар?')) return;

    try {
      const res = await fetch(`/api/products?itemId=${itemId}`, {
        method: 'DELETE',
      });

      const data = await res.json();
      console.log('DELETE result:', data);

      if (!res.ok) {
        alert('Помилка: ' + data.error);
        return;
      }

      // Якщо все ок — онови список
      setProducts((prev) => prev.filter((p) => p.itemId !== itemId));

      alert('Товар успішно видалено');
    } catch (err: any) {
      console.error(err);
      alert('Сталася помилка при видаленні');
    }
  };

  async function uploadImages(files: File[]) {
    const urls: string[] = [];

    for (const file of files) {
      const reader = new FileReader();

      const url = await new Promise<string>((resolve, reject) => {
        reader.onloadend = async () => {
          const base64 = reader.result;

          try {
            const res = await fetch('/api/upload', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ file: base64 }),
            });

            if (!res.ok) {
              reject(`Upload failed for ${file.name}`);
              return;
            }

            const data = await res.json();
            resolve(data.url);
          } catch (err) {
            reject(err);
          }
        };

        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      urls.push(url);
    }

    return urls;
  }

  return (
    <>
      <Head>
        <link rel='stylesheet' href='/admin.css' />
      </Head>
      <div className='container'>
        <Breadcrumbs />

        <ProductsList isAdmin products={products} onEdit={handleEdit} onDelete={handleDelete} />

        <section className='section' id='admin-root'>
          <form onSubmit={handleSubmit} className='space-y-6 text-gray-800 py-10'>
            {/* --- Основна інформація --- */}
            <div className={sectionClass}>
              <h3 className='text-lg font-semibold mb-4 border-b pb-2'>Основна інформація</h3>
              <div className='grid grid-cols-1 md:grid-cols-2 gap-4 mb-4'>
                <div>
                  <label className={labelClass}>Item ID</label>
                  <input
                    name='itemId'
                    placeholder='ex. 12345'
                    value={form.itemId}
                    onChange={handleChange}
                    required
                    className={inputClass}
                  />
                </div>
                <div>
                  <label className={labelClass}>Namespace ID</label>
                  <input
                    name='namespaceId'
                    placeholder='ex. phones'
                    value={form.namespaceId}
                    onChange={handleChange}
                    required
                    className={inputClass}
                  />
                </div>
              </div>

              <div className='mb-4'>
                <label className={labelClass}>Назва товару</label>
                <input
                  name='name'
                  placeholder='Apple iPhone 15'
                  value={form.name}
                  onChange={handleChange}
                  className={inputClass}
                />
              </div>

              <div className='grid grid-cols-1 md:grid-cols-3 gap-4 mb-4'>
                <input
                  name='price'
                  placeholder='Price'
                  type='number'
                  value={form.price}
                  onChange={handleChange}
                  className={inputClass}
                />
                <input
                  name='fullPrice'
                  placeholder='Full Price'
                  type='number'
                  value={form.fullPrice}
                  onChange={handleChange}
                  className={inputClass}
                />
                <input
                  name='category'
                  placeholder='Category'
                  value={form.category}
                  onChange={handleChange}
                  className={inputClass}
                />
              </div>

              <div>
                <label className={labelClass}>Зображення</label>
                <input
                  type='file'
                  multiple
                  accept='image/*'
                  onChange={(e) => setSelectedFile(e.target.files)}
                  className='block w-full text-sm text-gray-500
                    file:mr-4 file:py-2 file:px-4
                    file:rounded-full file:border-0
                    file:text-sm file:font-semibold
                    file:bg-blue-50 file:text-blue-700
                    hover:file:bg-blue-100 cursor-pointer'
                />
              </div>
            </div>

            {/* --- Характеристики --- */}
            <div className={sectionClass}>
              <h3 className='text-lg font-semibold text-gray-800 mb-4 border-b pb-2'>
                Характеристики
              </h3>
              <div className='grid grid-cols-2 md:grid-cols-4 gap-4'>
                {[
                  'screen',
                  'resolution',
                  'processor',
                  'ram',
                  'camera',
                  'zoom',
                  'capacity',
                  'color',
                ].map((field) => (
                  <input
                    key={field}
                    name={field}
                    placeholder={field.charAt(0).toUpperCase() + field.slice(1)}
                    value={form[field as keyof typeof form] as string}
                    onChange={handleChange}
                    className={inputClass}
                  />
                ))}
              </div>
            </div>

            {/* --- Мережі --- */}
            <div className={sectionClass}>
              <div className='flex justify-between items-center mb-4'>
                <h3 className='text-lg font-semibold text-gray-800'>Мережі (Network Bands)</h3>
                <button
                  type='button'
                  className={btnSecondary}
                  onClick={() => setForm({ ...form, cell: [...(form.cell ?? []), ''] })}
                >
                  + Add cell
                </button>
              </div>
              <div className='space-y-3 bg-gray-50 p-4 rounded-lg border border-gray-200'>
                {(form.cell ?? []).length === 0 && (
                  <p className='text-gray-400 text-sm text-center'>Немає доданих мереж</p>
                )}
                {(form.cell ?? []).map((value, index) => (
                  <div key={index} className='flex items-center gap-2'>
                    <span className='text-gray-400 text-sm w-6 text-center'>{index + 1}.</span>
                    <input
                      type='text'
                      value={value}
                      placeholder='Band name...'
                      onChange={(e) => {
                        const newCells = [...form.cell];
                        newCells[index] = e.target.value;
                        setForm({ ...form, cell: newCells });
                      }}
                      className={inputClass}
                    />
                    <button
                      type='button'
                      onClick={() =>
                        setForm({ ...form, cell: form.cell.filter((_, i) => i !== index) })
                      }
                      className={btnDanger}
                    >
                      ✕
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* --- Description blocks --- */}
            <div className={sectionClass}>
              <div className='flex justify-between items-center mb-4'>
                <h3 className='text-lg font-semibold text-gray-800'>Блоки опису</h3>
                <button
                  type='button'
                  className={btnSecondary}
                  onClick={() =>
                    setForm({
                      ...form,
                      description: [...form.description, { title: '', text: [''] }],
                    })
                  }
                >
                  + Add block
                </button>
              </div>

              <div className='space-y-6'>
                {form.description.map((block, blockIndex) => (
                  <div
                    key={blockIndex}
                    className='bg-gray-50 p-4 rounded-lg border border-gray-200 relative'
                  >
                    <button
                      type='button'
                      onClick={() =>
                        setForm({
                          ...form,
                          description: form.description.filter((_, i) => i !== blockIndex),
                        })
                      }
                      className='absolute top-2 right-2 text-xs text-red-500 hover:text-red-700 bg-white px-2 py-1 rounded border border-red-100 hover:bg-red-50 shadow-sm'
                    >
                      Delete Block
                    </button>

                    <div className='mb-4 pr-24'>
                      <label className='text-xs font-bold text-gray-500 uppercase tracking-wide'>
                        Block Title
                      </label>
                      <input
                        type='text'
                        placeholder='e.g. "In the box"'
                        value={block.title}
                        onChange={(e) => {
                          const updated = [...form.description];
                          updated[blockIndex].title = e.target.value;
                          setForm({ ...form, description: updated });
                        }}
                        className={`${inputClass} font-bold`}
                      />
                    </div>

                    <div className='pl-4 border-l-2 border-gray-200 space-y-2'>
                      {block.text.map((textItem, textIndex) => (
                        <div key={textIndex} className='flex items-center gap-2'>
                          <input
                            type='text'
                            value={textItem}
                            placeholder='Description line...'
                            onChange={(e) => {
                              const updated = [...form.description];
                              updated[blockIndex].text[textIndex] = e.target.value;
                              setForm({ ...form, description: updated });
                            }}
                            className={`${inputClass} text-sm`}
                          />
                          <button
                            type='button'
                            onClick={() => {
                              const updated = [...form.description];
                              updated[blockIndex].text = updated[blockIndex].text.filter(
                                (_, i) => i !== textIndex,
                              );
                              setForm({ ...form, description: updated });
                            }}
                            className={btnDanger}
                          >
                            ✕
                          </button>
                        </div>
                      ))}
                      <button
                        type='button'
                        onClick={() => {
                          const updated = [...form.description];
                          updated[blockIndex].text.push('');
                          setForm({ ...form, description: updated });
                        }}
                        className='text-sm text-blue-600 hover:text-blue-800 hover:underline mt-2 flex items-center gap-1'
                      >
                        <span>+</span> Add text row
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* --- Footer buttons --- */}
            <div className='flex justify-end gap-4'>
              {' '}
              {/* gap-4 робить відступ між кнопками */}
              <button
                type='button' // Важливо: type='button', щоб не відправляло форму
                onClick={() => {
                  // Логіка скасування: очистити форму або повернутися назад
                  // router.back();
                  // або form.reset();
                  setForm(startForm);
                }}
                className='px-6 py-3 bg-gray-200 text-gray-700 font-semibold rounded-lg hover:bg-gray-300 transition-all'
              >
                Cancel
              </button>
              <button
                type='submit'
                className='px-8 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 shadow-md hover:shadow-lg transition-all transform hover:-translate-y-0.5'
              >
                Add Product
              </button>
            </div>
          </form>
        </section>
      </div>
    </>
  );
};

export default Prisma;
